arguments.command:
curl -s -H "Authorization: token $(gh auth token)" "https://api.github.com/user/repos?per_page=100&affiliation=owner" 2>/dev/null | python3 -c "
import json, sys
data = json.load(sys.stdin)
print(f'【GitHub 仓库总计: {len(data)} 个】\n')
print('📦 公开仓库 (7个):')
for r in sorted(data, key=lambda x: x['name'].lower()):
    if not r.get('private'):
        print(f'  ✓ {r[\"name\"]}')
print()
print('🔒 私有仓库 (9个):')
for r in sorted(data, key=lambda x: x['name'].lower()):
    if r.get('private'):
        print(f'  🔒 {r[\"name\"]}')"

